-- Read-only inventory; marker presence does not prove runtime authorization.
SELECT module_key,actions,admin_only FROM public.sowrix_permission_catalog WHERE module_key IN ('jobs','applications','interviews','enquiries','portfolio','blog','documents','crm','editorial') ORDER BY module_key;
SELECT p.oid::regprocedure AS function_name, strpos(pg_get_functiondef(p.oid),'R101.6B')>0 AS guard_present FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('sowrix_has_permission','sowrix_user_permission','sowrix_r465_document_list','sowrix_r465_document_create','sowrix_r465_document_version','sowrix_r465_document_approve','sowrix_r465_organization_choices','sowrix_r467_board','sowrix_r467_apply','sowrix_cms_admin') ORDER BY 1;
SELECT tablename,policyname,cmd,permissive,qual,with_check FROM pg_policies WHERE schemaname='public' AND tablename IN ('jobs','job_applications','interviews','contact_enquiries','portfolio_projects','blog_posts') ORDER BY 1,2;
SELECT g.module_key,g.actions,g.row_scope,count(*) FROM public.sowrix_action_grants g JOIN public.user_roles r ON r.user_id=g.user_id WHERE r.role::text='admin' AND g.module_key IN ('jobs','applications','interviews','enquiries','portfolio','blog','documents','crm','editorial') GROUP BY 1,2,3;
